'TCT':'S','TCC':'S','TCA':'S','TCG':'S','CCT':'P','CCC':'P','CCA':'P','CCG':'P',
'ACT':'T','ACC':'T','ACA':'T','ACG':'T','GCT':'A','GCC':'A','GCA':'A','GCG':'A',
'TAT':'Y','TAC':'Y','TAA':'*','TAG':'*','CAT':'H','CAC':'H','CAA':'Q','CAG':'Q',
'AAT':'N','AAC':'N','AAA':'K','AAG':'K','GAT':'D','GAC':'D','GAA':'E','GAG':'E',
'TGT':'C','TGC':'C','TGA':'*','TGG':'W','CGT':'R','CGC':'R','CGA':'R','CGG':'R',
'AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G'}

def translate(s):
    return ''.join(code.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))

def find_orfs(s, minlen=60):
    """Return (start_idx0, end_exclusive_idx0, frame, prot) for ORFs ATG..stop (or end)."""
    orfs = []
    for strand, ss in [('+', s), ('-', revcomp(s))]:
        for frame in range(3):
            i = frame
            n = len(ss)
            while i + 2 < n:
                if ss[i:i+3] == 'ATG':
                    # extend to next in-frame stop
                    j = i
                    prot = []
                    while j + 2 < n:
                        aa = code[ss[j:j+3]]
                        prot.append(aa)
                        if aa == '*':
                            break
                        j += 3
                    plen = len(prot) - (1 if prot and prot[-1]=='*' else 0)
                    if plen >= 20:  # min 60 nt
                        orfs.append((strand, frame, i, j+3, ''.join(prot)))
                    i = j + 3
                else:
                    i += 3
    return orfs

orfs = find_orfs(seq)
