def translate_s(ss, table_ok=True):
    bases='TCAG'; aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
    t={a+b+c:aas[i] for i,(a,b,c) in enumerate((x,y,z) for x in bases for y in bases for z in bases)}
    return ''.join(t[ss[i:i+3]] for i in range(0,len(ss)-2,3))

# RBS check for each candidate ORF
orfs = {'A':(1161,2177,'+'), 'B':(237,953,'-'), 'C':(2215,2694,'-'), 'D':(2691,2996,'-'), 'E':(950,1198,'+')}
for name,(s,e,strand) in orfs.items():
    if strand=='+':
        up = seq[s-15:s-1]
    else:
        s_stop_e = e
        up = revcomp(seq[e:e+14])   # upstream of start (in minus frame)
    print(f"ORF {name} {s}..{e} ({strand}) upstream(3'->5' logical): {up}")

# protein motif scans on the big ORF
prot = translate_s(seq[1160:2177])[:-1]
for name, pat in [("P-loop NTP (GxxxxGKS/T)", r'G..{4}GKS'),
                  ("Walker A alt", r'[AG].{4}GKS'),
                  ("HTH helix-turn-helix loose", r'.{0,0}R.{2}[LIVMFY].{3}'),
                  ("Zn/Cys pairs", r'C..C'),
                  ("DEAD-box", r'DEAD'), ("Gly-Gly-x-Gly", r'GG.G')]:
    ms = [(m.start()+1, m.group()) for m in re.finditer(pat, prot)]
    if ms: print(f"{name}: {ms}")

# nucleotide repeats
print("\nTandem/repeated k-mers (>=2 copies of k>=9, own overlaps):")
for k in (15,12,10,9):
    seen={}
    found=False
    for i in range(len(seq)-k+1):
        w=seq[i:i+k]
        if w in seen: seen[w].append(i+1)
        else: seen[w]=[i+1]
    hits=[(w,v) for w,v in seen.items() if len(v)>1]
    if hits:
        print(f"k={k}:")
        for w,v in hits[:15]: print("  ",w,v)
        found=True
    if found: break

# inverted repeats (potential hairpins/terminators): stem >=12 with loop 3-10
best=[]
r=rc
s2=seq+'#'
lpal = lambda s: s.translate(str.maketrans('ACGT','TGCA'))[::-1]
window_terms=[]
for i in range(len(seq)-60):
    sub=seq[i:i+60]
    for stem in range(14,11,-1):
        # look for x.stem loop x.rc(stem) inside
        for j in range(0, len(sub)-2*stem-(3)+1):
            for loop in range(3,11):
                if j+2*stem+loop>len(sub): continue
                a=sub[j:j+stem]; b=sub[j+stem+loop:j+stem+loop+stem]
                if a==lpal(b):
                    window_terms.append((i+1,stem,loop,a))
print("\nQ-agnostic palindromes with stem>=14:", sorted(set(window_terms), key=lambda x:-x[1])[:8])
